// SETTINGS arrives as one item per row (key | value | type | description).
// Turn it into ONE item, e.g. { DEMO_MODE: 'TRUE', GEMINI_MODEL: 'gemini-2.5-flash', ... },
// so every later node can read settings with $('Lane 1 · Settings to object').first().json.KEY
const settings = {};
for (const item of $input.all()) {
  const key = String(item.json.key ?? '').trim();
  if (!key) continue;
  const value = item.json.value;
  settings[key] = typeof value === 'string' ? value.trim() : (value ?? '');
}

// Stop early with a clear message if the sheet is missing something Lane 1 needs.
const required = [
  'DEMO_MODE', 'DEMO_MINUTES_PER_DAY', 'LAUNCH_DATE', 'LAUNCH_TIME', 'EARLY_ACCESS_DAYS',
  'WAITLIST_FORM_URL', 'TELEGRAM_OWNER_CHAT_ID', 'BRAND_VOICE', 'GEMINI_MODEL', 'GROQ_MODEL',
  'AI_TEMPERATURE', 'AI_WAIT_SECONDS', 'POST_TIMES', 'CONTENT_START_IN_DAYS',
];
const missing = required.filter((key) => settings[key] === undefined || settings[key] === '');
if (missing.length) {
  throw new Error(`The SETTINGS tab is missing a value for: ${missing.join(', ')}`);
}

// Derived values (SPEC section 5.3). Sheet booleans may come back as true or "TRUE".
settings.IS_DEMO = String(settings.DEMO_MODE).trim().toUpperCase() === 'TRUE';
const demoMinutes = Number(settings.DEMO_MINUTES_PER_DAY);
if (settings.IS_DEMO && !(demoMinutes > 0)) {
  throw new Error('DEMO_MINUTES_PER_DAY must be a number above 0 when DEMO_MODE is TRUE');
}
settings.DAY_MS = settings.IS_DEMO ? demoMinutes * 60 * 1000 : 24 * 60 * 60 * 1000;

return [{ json: settings }];

// Turn the BRIEF rows into the text blocks every AI prompt uses, plus the lists the
// quality checks need (allowed prices, forbidden phrases). The AI may only use these facts.
const S = $('Lane 1 · Settings to object').first().json;
const TZ = 'Asia/Kolkata';
const rows = $input.all().map((item) => item.json).filter((row) => String(row.key ?? '').trim());

// Dates can come back from Sheets as text (2026-10-26) or, if the cell was auto-formatted, 26/10/2026.
function parseDate(value) {
  const text = String(value ?? '').trim();
  for (const format of [null, 'dd/MM/yyyy', 'd/M/yyyy']) {
    const date = format ? DateTime.fromFormat(text, format, { zone: TZ }) : DateTime.fromISO(text, { zone: TZ });
    if (date.isValid) return date;
  }
  throw new Error(`SETTINGS LAUNCH_DATE "${text}" is not a date. Use the format 2026-10-26.`);
}
const [hour, minute] = String(S.LAUNCH_TIME).split(':').map(Number);
const launch = parseDate(S.LAUNCH_DATE).set({ hour: hour || 0, minute: minute || 0 });
const publicLaunch = launch.plus({ days: Number(S.EARLY_ACCESS_DAYS) || 0 });

// Tokens allowed inside BRIEF values (SPEC section 6.3).
const tokens = {
  launch_date: launch.toFormat('cccc, d LLLL'),
  public_launch_date: publicLaunch.toFormat('cccc, d LLLL'),
  waitlist_form_url: S.WAITLIST_FORM_URL,
};
const fill = (text) => String(text ?? '').replace(/\{\{\s*(\w+)\s*\}\}/g, (match, key) => (key in tokens ? tokens[key] : match));

const byKey = {};
for (const row of rows) byKey[String(row.key).trim()] = fill(row.value);

const needed = ['brand_name', 'brand_instagram', 'collection_name', 'campaign_name', 'offer_code', 'offer_percent', 'seo_keywords', 'forbidden_phrases'];
const missing = needed.filter((key) => !byKey[key]);
if (missing.length) throw new Error(`The BRIEF tab is missing: ${missing.join(', ')}`);

// Lane 1 writes consumer content, so it uses facts marked "all" or "consumer" and every "rule".
const aiUse = (row) => String(row.ai_use ?? '').trim().toLowerCase();
const factRows = rows.filter((row) => ['all', 'consumer'].includes(aiUse(row)));
const ruleRows = rows.filter((row) => aiUse(row) === 'rule');
const factsText = factRows
  .map((row, index) => `F${String(index + 1).padStart(2, '0')} [${String(row.key).trim()}] ${fill(row.value)}`)
  .join('\n');
const rulesText = ruleRows.map((row) => `- ${String(row.key).trim()}: ${fill(row.value)}`).join('\n');

// Numbers the AI is allowed to print. Anything else is flagged by the quality checks.
const allFactText = factRows.map((row) => fill(row.value)).join('\n');
const toNumber = (text) => Number(String(text).replace(/[^\d.]/g, ''));
const allowedPrices = [...new Set((allFactText.match(/₹\s?[\d,]+/g) || []).map(toNumber))];
const allowedPercents = [...new Set((allFactText.match(/\d+(?:\.\d+)?\s?%/g) || []).map(toNumber))];
const splitList = (text) => String(text).split(';').map((part) => part.trim()).filter(Boolean);

return [{
  json: {
    brand_name: byKey.brand_name,
    brand_instagram: byKey.brand_instagram,
    collection_name: byKey.collection_name,
    campaign_name: byKey.campaign_name,
    offer_code: byKey.offer_code,
    offer_percent: byKey.offer_percent,
    launch_date: tokens.launch_date,
    public_launch_date: tokens.public_launch_date,
    waitlist_form_url: S.WAITLIST_FORM_URL,
    facts_text: factsText,
    rules_text: rulesText,
    fact_count: factRows.length,
    seo_keywords: splitList(byKey.seo_keywords),
    forbidden_phrases: splitList(byKey.forbidden_phrases).map((phrase) => phrase.toLowerCase()),
    allowed_prices: allowedPrices,
    allowed_percents: allowedPercents,
  },
}];

// One item per AI job. The loop after this node handles them one at a time.
// The blog MUST stay first: the last job (repurpose) reads the blog written in round 1.
const batchId = `B-${$now.setZone('Asia/Kolkata').toFormat('yyyyMMdd-HHmmss')}`;

const jobs = [
  { job_type: 'blog_article', label: 'Blog article + SEO fields' },
  { job_type: 'ig_captions', label: '5 Instagram captions' },
  { job_type: 'reel_ideas', label: '3 reel ideas' },
  { job_type: 'newsletter', label: 'Newsletter' },
  { job_type: 'blog_repurpose', label: 'Blog repurposed into 3 short posts' },
];

return jobs.map((job, index) => ({
  json: {
    batch_id: batchId,
    job_no: index + 1,
    request_id: `${batchId}:${job.job_type}`,
    ...job,
  },
}));

// Builds the prompt for the current job, plus the exact request bodies for Gemini (main)
// and Groq (fallback). Both providers get the same instructions and the same BRIEF facts.
const S = $('Lane 1 · Settings to object').first().json;
const B = $('Lane 1 · Build brief facts').first().json;
const job = $input.first().json;

const system = [
  `You are the in-house content writer for ${B.brand_name} (${B.brand_instagram}), a handmade jewellery brand from Jaipur that sells on Instagram in India.`,
  `Campaign: ${B.campaign_name}.`,
  '',
  'BRAND VOICE',
  S.BRAND_VOICE,
  '',
  'FACT RULES (most important)',
  '1. The BRIEF FACTS below are the only source of truth. Use nothing else.',
  '2. Never invent or change product names, prices, materials, discounts, codes, dates, shipping or delivery promises, stock levels, reviews, awards, statistics, people or quotes.',
  '3. If you need a detail that is not in the facts, leave it out or stay general (no numbers).',
  '4. Write prices exactly as they appear in the facts, for example ₹2,450.',
  `5. The only offer you may mention is the waitlist offer: early access plus ${B.offer_percent}% off.`,
  `6. Every call to action points to the waitlist. Instagram text says "link in bio". Where a real link is needed, use exactly: ${B.waitlist_form_url}`,
  '',
  'WRITING RULES',
  B.rules_text,
  '',
  'BRIEF FACTS',
  B.facts_text,
  '',
  'Answer with one JSON object only. No markdown fences, no comments.',
].join('\n');

// Gemini "responseSchema" types (OpenAPI subset, upper case).
const str = (description) => ({ type: 'STRING', description });
const list = (items, min, max) => ({ type: 'ARRAY', items, minItems: min, maxItems: max });
const obj = (properties) => ({ type: 'OBJECT', properties, required: Object.keys(properties), propertyOrdering: Object.keys(properties) });

// Look back at earlier loop rounds for the blog (it is always job 1). Used by the repurpose job.
function findBlog() {
  for (let round = 0; round < $runIndex; round++) {
    const previous = $('Lane 1 · Pause between AI calls').all(0, round)[0]?.json;
    if (previous?.job_type === 'blog_article' && previous.ai_ok) return previous.ai_data;
  }
  return null;
}

const JOBS = {
  blog_article: () => ({
    maxTokens: 4000,
    prompt: [
      `Write one SEO blog article for the ${B.brand_name} website about the ${B.collection_name} Diwali launch.`,
      `- target_keyword: choose ONE phrase from this list and copy it exactly: ${B.seo_keywords.join(' | ')}.`,
      '- article_markdown: 600 to 900 words of Markdown. Start with exactly one H1 line ("# ..."). Then 3 to 5 H2 sections ("## ..."). H3 ("### ...") only inside an H2 section. No H4.',
      '- Put the exact target keyword in the H1, in the first paragraph and in at least one H2.',
      '- Short paragraphs of 2 to 4 sentences. Keep the average sentence under 18 words. Use plain, everyday words.',
      '- Mention at least 3 products from the facts with their exact prices.',
      `- End with a short section inviting readers to join the waitlist for early access and ${B.offer_percent}% off, with this Markdown link: [Join the waitlist](${B.waitlist_form_url})`,
      '- seo_title: at most 60 characters, contains the target keyword.',
      '- meta_description: 120 to 155 characters, contains the target keyword, ends with a call to action.',
      '- slug: lowercase words joined by hyphens, at most 60 characters, based on the target keyword.',
    ].join('\n'),
    schema: obj({
      target_keyword: str('Exactly one phrase from the allowed keyword list'),
      seo_title: str('At most 60 characters, contains the target keyword'),
      meta_description: str('120 to 155 characters, contains the target keyword'),
      slug: str('lowercase-words-with-hyphens, at most 60 characters'),
      article_markdown: str('600 to 900 words of Markdown starting with one H1'),
    }),
    example: {
      target_keyword: 'one phrase from the list',
      seo_title: 'max 60 characters',
      meta_description: '120-155 characters',
      slug: 'lowercase-hyphen-slug',
      article_markdown: '# H1 title\n\nFirst paragraph...\n\n## H2 ...',
    },
  }),

  ig_captions: () => ({
    maxTokens: 2500,
    prompt: [
      `Write 5 different Instagram captions for the weeks before early access to ${B.collection_name} opens.`,
      'Use these 5 angles, one each, in this order: 1) collection reveal teaser, 2) the artisans and the handmade process, 3) one product spotlight with its exact price, 4) Diwali gifting, 5) the waitlist offer (early access + 10% off).',
      'For each caption:',
      '- angle: the angle name.',
      '- hook: the first line, at most 125 characters, scroll-stopping, no hashtags.',
      '- caption: the full caption starting with the hook line, 60 to 150 words, line breaks allowed, at most 3 emojis, ending with a call to action to join the waitlist via the link in bio. No hashtags inside the caption.',
      '- hashtags: 8 to 12 hashtags, each starting with #, always including #KayaJewels and #RoshniEdit.',
      '- cta: the call-to-action sentence you used.',
      '- image_idea: one sentence describing the photo or carousel to pair with it, using only products from the facts.',
    ].join('\n'),
    schema: obj({
      captions: list(obj({
        angle: str('Angle name'),
        hook: str('First line, max 125 characters'),
        caption: str('Full caption, 60-150 words, no hashtags'),
        hashtags: list({ type: 'STRING' }, 8, 12),
        cta: str('Call-to-action sentence'),
        image_idea: str('Photo idea'),
      }), 5, 5),
    }),
    example: {
      captions: [{ angle: '...', hook: '...', caption: '...', hashtags: ['#KayaJewels', '#RoshniEdit'], cta: '...', image_idea: '...' }],
    },
  }),

  reel_ideas: () => ({
    maxTokens: 2500,
    prompt: [
      `Write 3 short vertical video (Instagram Reel) ideas for the ${B.collection_name} launch.`,
      'Use these 3 angles, one each: 1) making-of in the Jaipur studio, 2) styling one product three ways for Diwali, 3) unboxing the gift box.',
      'For each idea:',
      '- title: a short internal name.',
      '- hook: what is said or shown in the first 2 seconds, at most 12 words.',
      '- shot_list: 4 to 7 shots, each a short instruction a phone videographer can follow (what to film, close-up or wide, the action).',
      '- caption: the reel caption, 40 to 100 words, ending with the waitlist call to action (link in bio). No hashtags inside the caption.',
      '- hashtags: 5 to 10 hashtags including #KayaJewels and #RoshniEdit.',
      '- audio_idea: the mood or type of audio to use. Do not name copyrighted songs.',
      '- duration_seconds: a whole number from 15 to 45.',
    ].join('\n'),
    schema: obj({
      reels: list(obj({
        title: str('Short internal name'),
        hook: str('First 2 seconds, max 12 words'),
        shot_list: list({ type: 'STRING' }, 4, 7),
        caption: str('Reel caption, 40-100 words'),
        hashtags: list({ type: 'STRING' }, 5, 10),
        audio_idea: str('Audio mood'),
        duration_seconds: { type: 'INTEGER', description: '15 to 45' },
      }), 3, 3),
    }),
    example: {
      reels: [{ title: '...', hook: '...', shot_list: ['...', '...', '...', '...'], caption: '...', hashtags: ['#KayaJewels', '#RoshniEdit'], audio_idea: '...', duration_seconds: 30 }],
    },
  }),

  newsletter: () => ({
    maxTokens: 2500,
    prompt: [
      `Write one email newsletter to people already on the waitlist. It builds excitement for ${B.collection_name} and reminds them that early access is reserved for them.`,
      '- subject: at most 60 characters, no ALL CAPS words, at most 1 emoji.',
      '- preview_text: 60 to 110 characters, shown after the subject in the inbox.',
      '- html_body: a simple HTML email body of 150 to 300 words. Use only <p>, <h2>, <ul>, <li>, <strong>, <em>, <a> and <br>. No <html>, <head>, <body>, <style>, images, classes or scripts.',
      '  - The very first element must be exactly: <p>Hi {{first_name}},</p>',
      '  - Mention at least 2 products with their exact prices, the early-access dates and the waitlist offer.',
      `  - Include one link inviting them to share the waitlist with a friend: <a href="${B.waitlist_form_url}">Share the waitlist with a friend</a>`,
      '  - The very last element must be exactly: <p>{{unsubscribe_line}}</p>',
      '  - Keep {{first_name}} and {{unsubscribe_line}} exactly as written; they are filled in later.',
    ].join('\n'),
    schema: obj({
      subject: str('Max 60 characters'),
      preview_text: str('60-110 characters'),
      html_body: str('Simple HTML body, 150-300 words'),
    }),
    example: { subject: '...', preview_text: '...', html_body: '<p>Hi {{first_name}},</p>...<p>{{unsubscribe_line}}</p>' },
  }),

  blog_repurpose: () => {
    const blog = findBlog();
    const source = blog
      ? `BLOG ARTICLE TO REPURPOSE\n${blog.article_markdown}`
      : `The blog article failed, so base the posts on the facts about ${B.collection_name} instead.`;
    return {
      maxTokens: 2000,
      prompt: [
        'Repurpose the blog article below into 3 short social posts (Instagram stories, Threads or WhatsApp status style).',
        'Each post takes a different idea from the article and must make sense on its own.',
        'For each post:',
        '- angle: 3 to 6 words naming the idea.',
        '- text: at most 280 characters including emojis, ending with a short call to action such as "Waitlist link in bio".',
        '- hashtags: 2 to 4 hashtags including #RoshniEdit.',
        'Use only information that is in the article AND in the facts.',
        '',
        source,
      ].join('\n'),
      schema: obj({
        short_posts: list(obj({
          angle: str('3-6 words'),
          text: str('Max 280 characters'),
          hashtags: list({ type: 'STRING' }, 2, 4),
        }), 3, 3),
      }),
      example: { short_posts: [{ angle: '...', text: '...', hashtags: ['#RoshniEdit', '#KayaJewels'] }] },
    };
  },
};

if (!JOBS[job.job_type]) throw new Error(`Unknown job_type: ${job.job_type}`);
const spec = JOBS[job.job_type]();
const temperature = Number(S.AI_TEMPERATURE);
// Gemini 2.5 models "think" before answering, and thinking tokens count against maxOutputTokens.
// A cap keeps room for the answer. Blank setting = do not send it (models without thinking reject it).
const thinkingBudget = String(S.GEMINI_THINKING_BUDGET ?? '').trim();

return [{
  json: {
    ...job,
    gemini_model: String(S.GEMINI_MODEL).replace(/^models\//, ''),
    groq_model: S.GROQ_MODEL,
    started_at: Date.now(),
    // Gemini generateContent body: JSON mode + schema = the answer is always valid JSON.
    gemini_body: {
      systemInstruction: { parts: [{ text: system }] },
      contents: [{ role: 'user', parts: [{ text: spec.prompt }] }],
      generationConfig: {
        temperature: Number.isFinite(temperature) ? temperature : 0.7,
        maxOutputTokens: 8192,
        responseMimeType: 'application/json',
        responseSchema: spec.schema,
        ...(thinkingBudget !== '' && Number.isFinite(Number(thinkingBudget)) ? { thinkingConfig: { thinkingBudget: Number(thinkingBudget) } } : {}),
      },
    },
    // Groq (OpenAI-compatible) body: JSON mode + an example of the expected shape.
    groq_body: {
      model: S.GROQ_MODEL,
      temperature: Number.isFinite(temperature) ? temperature : 0.7,
      max_tokens: spec.maxTokens,
      response_format: { type: 'json_object' },
      messages: [
        {
          role: 'system',
          content: `${system}\n\nOUTPUT FORMAT\nReturn ONLY one JSON object with exactly this shape (same keys, same types; arrays must have the requested number of entries):\n${JSON.stringify(spec.example)}`,
        },
        { role: 'user', content: spec.prompt },
      ],
    },
  },
}];

// Pull the answer text out of Gemini's response. If the HTTP call failed (after its retries),
// the item only has an "error" field; we pass that on so the check can switch to Groq.
const request = $('Lane 1 · Build AI request').first().json;
const response = $input.first().json;

let text = '';
let error = '';
if (response.error) {
  const { message, description } = response.error;
  const detail = [message, description].filter(Boolean).join(' - ') || JSON.stringify(response.error);
  error = `Gemini call failed: ${String(detail).slice(0, 300)}`;
} else {
  const candidate = (response.candidates || [])[0];
  const parts = candidate?.content?.parts || [];
  // Skip "thought" parts that thinking models may add; keep only the answer text.
  text = parts.filter((part) => !part.thought && typeof part.text === 'string').map((part) => part.text).join('');
  const finish = candidate?.finishReason || response.promptFeedback?.blockReason || 'unknown';
  if (!text) error = `Gemini returned no text (reason: ${finish})`;
  else if (finish !== 'STOP') error = `Gemini stopped early (reason: ${finish})`;
}

return [{ json: { provider: 'gemini', model: request.gemini_model, text, error, fallback_reason: '' } }];

// Same check for both providers: is the answer valid JSON with everything we asked for?
// If Gemini's answer is not usable, try_groq = true sends the job to the Groq fallback.
const S = $('Lane 1 · Settings to object').first().json;
const request = $('Lane 1 · Build AI request').first().json;
const reply = $input.first().json;

function parseJson(text) {
  let clean = String(text || '').trim().replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '').trim();
  const start = clean.indexOf('{');
  const end = clean.lastIndexOf('}');
  if (start !== -1 && end > start) clean = clean.slice(start, end + 1);
  return JSON.parse(clean);
}

const filled = (value) => String(value ?? '').trim() !== '';
const countFilled = (list, field) => (Array.isArray(list) ? list.filter((entry) => entry && filled(entry[field])).length : 0);

// Minimum shape per job. Finer quality rules live in "SEO & quality checks".
const RULES = {
  blog_article: (data) => {
    const problems = ['target_keyword', 'seo_title', 'meta_description', 'slug', 'article_markdown']
      .filter((field) => !filled(data[field])).map((field) => `missing ${field}`);
    if (String(data.article_markdown || '').split(/\s+/).length < 300) problems.push('article is far too short');
    return problems;
  },
  ig_captions: (data) => (countFilled(data.captions, 'caption') >= 5 ? [] : ['needs 5 captions']),
  reel_ideas: (data) => (countFilled(data.reels, 'hook') >= 3 ? [] : ['needs 3 reel ideas']),
  newsletter: (data) => ['subject', 'preview_text', 'html_body'].filter((field) => !filled(data[field])).map((field) => `missing ${field}`),
  blog_repurpose: (data) => (countFilled(data.short_posts, 'text') >= 3 ? [] : ['needs 3 short posts']),
};

let data = null;
let error = reply.error || '';
if (!error) {
  try {
    data = parseJson(reply.text);
  } catch (parseError) {
    error = `${reply.provider} answer is not valid JSON: ${parseError.message}`;
  }
}
if (!error) {
  const problems = RULES[request.job_type](data);
  if (problems.length) error = `${reply.provider} answer is incomplete: ${problems.join(', ')}`;
}

const ok = !error;
const tryGroq = !ok && reply.provider === 'gemini';
return [{
  json: {
    batch_id: request.batch_id,
    job_no: request.job_no,
    job_type: request.job_type,
    label: request.label,
    request_id: request.request_id,
    ai_ok: ok,
    ai_provider: reply.provider,
    ai_model: reply.model,
    ai_error: error,
    fallback_reason: reply.fallback_reason || '',
    try_groq: tryGroq,
    duration_ms: Date.now() - request.started_at,
    ai_data: ok ? data : null,
    // Handed to the next nodes so their settings stay simple: {{ $json.groq_body }} / {{ $json.pause_seconds }}
    groq_body: tryGroq ? request.groq_body : null,
    pause_seconds: Math.max(0, Number(S.AI_WAIT_SECONDS) || 6),
  },
}];

// Pull the answer text out of Groq's (OpenAI-style) response, and remember why we fell back.
const request = $('Lane 1 · Build AI request').first().json;
const response = $input.first().json;
// The item that the IF node sent down its "true" branch carries Gemini's error.
const fallbackReason = $('Lane 1 · Need Groq fallback?').first(0)?.json?.ai_error || '';

let text = '';
let error = '';
if (response.error) {
  const { message, description } = response.error;
  const detail = [message, description].filter(Boolean).join(' - ') || JSON.stringify(response.error);
  error = `Groq call failed: ${String(detail).slice(0, 300)}`;
} else {
  const choice = (response.choices || [])[0];
  text = choice?.message?.content || '';
  if (!text) error = `Groq returned no text (reason: ${choice?.finish_reason || 'unknown'})`;
}

return [{ json: { provider: 'groq', model: request.groq_model, text, error, fallback_reason: fallbackReason } }];

// The loop is finished: one item per AI job. Split each answer into CONTENT rows:
// 1 blog + 5 captions + 3 reel ideas + 1 newsletter + 3 short posts = 13 rows when all jobs work.
const B = $('Lane 1 · Build brief facts').first().json;
const results = $input.all().map((item) => item.json);

const text = (value) => String(value ?? '').trim();
const hashtags = (value) => (Array.isArray(value) ? value : text(value).split(/[\s,]+/))
  .map((tag) => text(tag).replace(/\s+/g, ''))
  .filter(Boolean)
  .map((tag) => (tag.startsWith('#') ? tag : `#${tag}`))
  .join(' ');
const slugify = (value) => text(value).toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');

const rows = [];
for (const result of results) {
  if (!result.ai_ok) continue;
  const data = result.ai_data;
  const base = { ai_provider: result.ai_provider, seo_title: '', meta_description: '', slug: '', target_keyword: '', hashtags: '', cta: '', media_notes: '' };

  if (result.job_type === 'blog_article') {
    const markdown = text(data.article_markdown);
    const h1 = (markdown.match(/^#\s+(.+)$/m) || [])[1];
    rows.push({
      ...base,
      asset_type: 'blog_article',
      channel: 'blog',
      title: text(h1 || data.seo_title),
      body: markdown,
      cta: `Join the waitlist: ${B.waitlist_form_url}`,
      seo_title: text(data.seo_title),
      meta_description: text(data.meta_description),
      slug: slugify(data.slug || data.target_keyword),
      target_keyword: text(data.target_keyword).toLowerCase(),
    });
  }

  if (result.job_type === 'ig_captions') {
    for (const caption of data.captions.slice(0, 5)) {
      rows.push({
        ...base,
        asset_type: 'ig_caption',
        channel: 'instagram',
        title: text(caption.hook) || text(caption.caption).split('\n')[0],
        body: text(caption.caption),
        hashtags: hashtags(caption.hashtags),
        cta: text(caption.cta),
        media_notes: text(caption.image_idea),
      });
    }
  }

  if (result.job_type === 'reel_ideas') {
    for (const reel of data.reels.slice(0, 3)) {
      const shots = (Array.isArray(reel.shot_list) ? reel.shot_list : []).map((shot, index) => `${index + 1}. ${text(shot)}`);
      rows.push({
        ...base,
        asset_type: 'reel_idea',
        channel: 'reels',
        title: text(reel.title),
        body: text(reel.caption),
        hashtags: hashtags(reel.hashtags),
        cta: 'Waitlist link in bio',
        media_notes: [
          `Hook: ${text(reel.hook)}`,
          'Shots:',
          ...shots,
          `Audio: ${text(reel.audio_idea)}`,
          `Length: ${Number(reel.duration_seconds) || ''} seconds`,
        ].join('\n'),
      });
    }
  }

  if (result.job_type === 'newsletter') {
    rows.push({
      ...base,
      asset_type: 'newsletter',
      channel: 'email',
      title: text(data.subject),
      body: text(data.html_body),
      cta: 'Share the waitlist with a friend',
      meta_description: text(data.preview_text), // for newsletters this column holds the inbox preview text
    });
  }

  if (result.job_type === 'blog_repurpose') {
    for (const post of data.short_posts.slice(0, 3)) {
      rows.push({
        ...base,
        asset_type: 'short_post',
        channel: 'instagram',
        title: text(post.angle),
        body: text(post.text),
        hashtags: hashtags(post.hashtags),
        cta: 'Waitlist link in bio',
      });
    }
  }
}

if (!rows.length) {
  const reasons = results.map((result) => `${result.job_type}: ${result.ai_error}`).join(' | ');
  throw new Error(`Every AI job failed, so there is nothing to save. ${reasons}`);
}
return rows.map((json) => ({ json }));

// Score every row 0-100 and list its problems, so a human can approve quickly.
// Blog = SEO checks. Other assets = format checks. Every asset also gets a fact check
// against the BRIEF; each fact problem costs 10 points and is listed first, marked "FACT:".
const B = $('Lane 1 · Build brief facts').first().json;

// ---------- small helpers
const lower = (value) => String(value ?? '').toLowerCase();
const wordsOf = (value) => String(value ?? '').split(/\s+/).filter((word) => /[\p{L}\p{N}]/u.test(word));
const hasCta = (value) => /waitlist|link in bio/i.test(String(value));
const countEmojis = (value) => (String(value).match(/\p{Extended_Pictographic}/gu) || []).length;
const tagList = (value) => String(value ?? '').split(/\s+/).filter(Boolean);

function stripMarkdown(markdown) {
  return String(markdown)
    .replace(/!\[[^\]]*\]\([^)]*\)/g, ' ')
    .replace(/\[([^\]]+)\]\([^)]*\)/g, '$1')
    .replace(/^#{1,6}\s+/gm, '')
    .replace(/^\s*(?:[-*+]|\d+\.)\s+/gm, '')
    .replace(/[*_`>]/g, '');
}
const stripHtml = (html) => String(html).replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&');

// Flesch reading ease: 60+ is easy, 50-60 fairly easy, below 50 hard.
function syllables(word) {
  const clean = word.toLowerCase().replace(/[^a-z]/g, '');
  if (!clean) return 0;
  if (clean.length <= 3) return 1;
  const groups = clean.replace(/(?:[^laeiouy]es|ed|[^laeiouy]e)$/, '').replace(/^y/, '').match(/[aeiouy]{1,2}/g);
  return Math.max(1, groups ? groups.length : 1);
}
function readability(plain) {
  const words = wordsOf(plain);
  const sentences = String(plain).split(/[.!?]+(?=\s|$)/).filter((sentence) => wordsOf(sentence).length > 0);
  const avgSentence = words.length / Math.max(sentences.length, 1);
  const avgSyllables = words.reduce((sum, word) => sum + syllables(word), 0) / Math.max(words.length, 1);
  return { avgSentence, flesch: 206.835 - 1.015 * avgSentence - 84.6 * avgSyllables };
}

// checks = [[points, passed, problem text], ...] -> { score, issues }
function grade(checks) {
  const total = checks.reduce((sum, [points]) => sum + points, 0);
  const earned = checks.reduce((sum, [points, passed]) => sum + (passed ? points : 0), 0);
  return { score: Math.round((earned / total) * 100), issues: checks.filter(([, passed]) => !passed).map(([, , problem]) => problem) };
}

// ---------- fact check (all assets)
function factIssues(row) {
  const all = [row.title, row.body, row.cta, row.media_notes, row.seo_title, row.meta_description, row.hashtags].join('\n');
  const text = lower(all);
  const issues = [];
  for (const phrase of B.forbidden_phrases) {
    if (text.includes(phrase)) issues.push(`FACT: uses the forbidden phrase "${phrase}"`);
  }
  for (const price of all.match(/(?:₹|\brs\.?|\binr)\s?\d[\d,]*/gi) || []) {
    if (!B.allowed_prices.includes(Number(price.replace(/[^\d]/g, '')))) issues.push(`FACT: price ${price.trim()} is not in the brief`);
  }
  for (const percent of all.match(/\d+(?:\.\d+)?\s?%/g) || []) {
    if (!B.allowed_percents.includes(Number(percent.replace(/[^\d.]/g, '')))) issues.push(`FACT: "${percent}" is not in the brief`);
  }
  if (B.offer_code && text.includes(lower(B.offer_code))) issues.push('FACT: reveals the discount code before launch');
  return [...new Set(issues)];
}

// ---------- per asset type
function blogChecks(row) {
  const markdown = row.body;
  const keyword = lower(row.target_keyword).trim();
  const headings = markdown.split('\n')
    .map((line) => line.trim().match(/^(#{1,6})\s+(.*)$/))
    .filter(Boolean)
    .map((match) => ({ level: match[1].length, text: match[2] }));
  const h1 = headings.filter((heading) => heading.level === 1);
  const h2 = headings.filter((heading) => heading.level === 2);
  const skipsLevel = headings.some((heading, index) => index > 0 && heading.level > headings[index - 1].level + 1);
  const firstParagraph = markdown.split(/\n\s*\n/).map((block) => block.trim()).find((block) => block && !block.startsWith('#')) || '';
  const plain = stripMarkdown(markdown);
  const wordCount = wordsOf(plain).length;
  const { avgSentence, flesch } = readability(plain);
  const keywordHits = keyword ? lower(plain).split(keyword).length - 1 : 0;
  const density = wordCount ? ((keywordHits * keyword.split(/\s+/).length) / wordCount) * 100 : 0;
  const titleLength = row.seo_title.length;
  const metaLength = row.meta_description.length;
  const keywordWords = keyword.split(/\s+/).filter((word) => word.length > 3);
  const slugOk = /^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(row.slug) && row.slug.length <= 60 && keywordWords.every((word) => row.slug.includes(word));

  const result = grade([
    [10, titleLength > 0 && titleLength <= 60, `SEO title is ${titleLength} characters (max 60)`],
    [10, metaLength >= 120 && metaLength <= 155, `Meta description is ${metaLength} characters (aim for 120-155)`],
    [15, !!keyword && lower(row.seo_title).includes(keyword), 'Target keyword is missing from the SEO title'],
    [5, !!keyword && lower(row.meta_description).includes(keyword), 'Target keyword is missing from the meta description'],
    [10, !!keyword && lower(stripMarkdown(firstParagraph)).includes(keyword), 'Target keyword is missing from the first paragraph'],
    [10, !!keyword && h2.some((heading) => lower(heading.text).includes(keyword)), 'Target keyword is not in any H2 heading'],
    [10, h1.length === 1 && headings[0]?.level === 1 && h2.length >= 3 && !skipsLevel,
      `Heading structure needs 1 H1 first, 3+ H2 and no skipped levels (found ${h1.length} H1, ${h2.length} H2${skipsLevel ? ', a skipped level' : ''})`],
    [10, wordCount >= 600 && wordCount <= 900, `Article is ${wordCount} words (aim for 600-900)`],
    [10, flesch >= 50 && avgSentence <= 20, `Readability: Flesch score ${flesch.toFixed(0)} (aim for 50+), ${avgSentence.toFixed(1)} words per sentence (aim for 20 or fewer)`],
    [5, density >= 0.5 && density <= 2.5, `Keyword density is ${density.toFixed(1)}% (aim for 0.5-2.5%)`],
    [5, slugOk, `Slug "${row.slug}" should be lowercase-with-hyphens, max 60 characters, and contain the keyword`],
  ]);
  if (keyword && !B.seo_keywords.map(lower).includes(keyword)) {
    result.issues.push('Target keyword is not one of the BRIEF seo_keywords (no points lost)');
  }
  return result;
}

function captionChecks(row) {
  const firstLine = row.body.split('\n')[0];
  const words = wordsOf(row.body).length;
  const tags = tagList(row.hashtags).map(lower);
  const emojis = countEmojis(row.body);
  return grade([
    [20, firstLine.length <= 125, `Hook (first line) is ${firstLine.length} characters (max 125 shows before "more")`],
    [10, row.body.length <= 2200, `Caption is ${row.body.length} characters (Instagram max is 2,200)`],
    [15, words >= 40 && words <= 180, `Caption is ${words} words (aim for 60-150)`],
    [10, tags.length >= 5 && tags.length <= 15, `${tags.length} hashtags (aim for 8-12, max 15)`],
    [10, tags.includes('#kayajewels') && tags.includes('#roshniedit'), 'Missing #KayaJewels or #RoshniEdit'],
    [20, hasCta(row.body), 'No waitlist call to action ("waitlist" or "link in bio") in the caption'],
    [10, emojis <= 3, `${emojis} emojis (the brief allows 3)`],
    [5, !/#[\p{L}\p{N}]/u.test(row.body), 'Hashtags inside the caption text (keep them in the hashtags column)'],
  ]);
}

function reelChecks(row) {
  const notes = row.media_notes;
  const hookWords = wordsOf((notes.match(/^Hook: (.*)$/m) || [])[1]).length;
  const shots = (notes.match(/^\d+\. /gm) || []).length;
  const seconds = Number((notes.match(/^Length: (\d+)/m) || [])[1]);
  const audio = ((notes.match(/^Audio: (.*)$/m) || [])[1] || '').trim();
  const words = wordsOf(row.body).length;
  const tags = tagList(row.hashtags);
  return grade([
    [20, hookWords > 0 && hookWords <= 12, `Hook is ${hookWords} words (max 12)`],
    [20, shots >= 4 && shots <= 7, `${shots} shots in the shot list (aim for 4-7)`],
    [10, seconds >= 15 && seconds <= 45, `Length is ${seconds || 'unknown'} seconds (aim for 15-45)`],
    [15, words >= 30 && words <= 120, `Reel caption is ${words} words (aim for 40-100)`],
    [15, hasCta(row.body), 'No waitlist call to action in the reel caption'],
    [10, tags.length >= 5 && tags.length <= 10, `${tags.length} hashtags (aim for 5-10)`],
    [10, audio.length > 0, 'No audio idea'],
  ]);
}

function newsletterChecks(row) {
  const html = row.body;
  const words = wordsOf(stripHtml(html)).length;
  return grade([
    [15, row.title.length > 0 && row.title.length <= 60, `Subject is ${row.title.length} characters (max 60)`],
    [10, row.meta_description.length >= 40 && row.meta_description.length <= 140, `Preview text is ${row.meta_description.length} characters (aim for 60-110)`],
    [15, html.includes('{{first_name}}'), 'Missing the {{first_name}} placeholder'],
    [15, html.includes('{{unsubscribe_line}}'), 'Missing the {{unsubscribe_line}} placeholder'],
    [15, html.includes(B.waitlist_form_url), 'No link to the waitlist form'],
    [15, words >= 120 && words <= 350, `Body is ${words} words (aim for 150-300)`],
    [15, !/<\s*(script|style|html|head|body|img|iframe)\b/i.test(html), 'Body uses tags that are not allowed (script, style, html, head, body, img, iframe)'],
  ]);
}

function shortPostChecks(row) {
  const characters = [...row.body].length;
  const tags = tagList(row.hashtags);
  return grade([
    [40, characters <= 280, `Post is ${characters} characters (max 280)`],
    [30, hasCta(row.body), 'No waitlist call to action'],
    [30, tags.length >= 2 && tags.length <= 4, `${tags.length} hashtags (aim for 2-4)`],
  ]);
}

const CHECKS = {
  blog_article: blogChecks,
  ig_caption: captionChecks,
  reel_idea: reelChecks,
  newsletter: newsletterChecks,
  short_post: shortPostChecks,
};

return $input.all().map((item) => {
  const row = item.json;
  const quality = CHECKS[row.asset_type](row);
  const facts = factIssues(row);
  return {
    json: {
      ...row,
      seo_score: Math.max(0, quality.score - 10 * facts.length),
      issues: [...facts, ...quality.issues].join(' | '),
    },
  };
});

// Give every row an ID and a posting slot, then shape it into the exact CONTENT columns.
// Real mode: slots are POST_TIMES on the days after the run (from CONTENT_START_IN_DAYS on).
// Demo mode: the same calendar, squeezed so 1 day = DEMO_MINUTES_PER_DAY real minutes.
const S = $('Lane 1 · Settings to object').first().json;
const batchId = $('Lane 1 · List asset jobs').first().json.batch_id;
const TZ = 'Asia/Kolkata';
const STAMP = "yyyy-MM-dd'T'HH:mm:ssZZ";
const now = $now.setZone(TZ).startOf('second');
const rows = $input.all().map((item) => item.json);

// Calendar order: mix the formats so the feed never shows the same type three times in a row.
const ORDER = [
  'blog_article', 'ig_caption', 'newsletter', 'ig_caption', 'reel_idea', 'short_post', 'ig_caption',
  'short_post', 'reel_idea', 'ig_caption', 'short_post', 'ig_caption', 'reel_idea',
];
const queues = {};
for (const row of rows) (queues[row.asset_type] = queues[row.asset_type] || []).push(row);
const ordered = [];
for (const type of ORDER) if (queues[type]?.length) ordered.push(queues[type].shift());
for (const type of Object.keys(queues)) ordered.push(...queues[type]); // anything left over goes last

// Posting slots
const times = String(S.POST_TIMES).split(',').map((time) => time.trim()).filter(Boolean).sort();
if (!times.length) throw new Error('SETTINGS POST_TIMES needs at least one time, e.g. 11:00,19:00');
const startDays = Number(S.CONTENT_START_IN_DAYS) || 0;
const demoFactor = S.IS_DEMO ? Number(S.DEMO_MINUTES_PER_DAY) / (24 * 60) : 1;
function slot(index) {
  const [hour, minute] = times[index % times.length].split(':').map(Number);
  const real = now.startOf('day').plus({ days: startDays + Math.floor(index / times.length) }).set({ hour, minute });
  if (!S.IS_DEMO) return real;
  // Demo clock: keep the same distance from "now", just shorter (SPEC section 5.3).
  return now.plus({ milliseconds: Math.max(0, real.toMillis() - now.toMillis()) * demoFactor }).startOf('second');
}

const idFor = (index) => `CNT-${batchId.slice(2)}-${String(index + 1).padStart(2, '0')}`;
const blogIndex = ordered.findIndex((row) => row.asset_type === 'blog_article');
const created = now.toFormat(STAMP);

return ordered.map((row, index) => ({
  json: {
    content_id: idFor(index),
    batch_id: batchId,
    created_at: created,
    asset_type: row.asset_type,
    channel: row.channel,
    title: row.title,
    body: row.body,
    hashtags: row.hashtags,
    cta: row.cta,
    media_notes: row.media_notes,
    seo_title: row.seo_title,
    meta_description: row.meta_description,
    slug: row.slug,
    target_keyword: row.target_keyword,
    seo_score: row.seo_score,
    issues: row.issues,
    scheduled_for: slot(index).toFormat(STAMP),
    status: 'pending_approval',
    source_content_id: row.asset_type === 'short_post' && blogIndex !== -1 ? idFor(blogIndex) : '',
    ai_provider: row.ai_provider,
    review_notes: '',
    published_at: '',
    publish_ref: '',
    last_error: '',
    updated_at: created,
  },
}));

// One Telegram message to the owner: how many items wait for approval, a short list,
// and anything that went wrong. Telegram "HTML" mode, so user text must be escaped.
const S = $('Lane 1 · Settings to object').first().json;
const B = $('Lane 1 · Build brief facts').first().json;
const rows = $('Lane 1 · Schedule & assign IDs').all().map((item) => item.json);
const results = $('Lane 1 · Loop over asset jobs').all(0).map((item) => item.json); // the loop's "done" output
const TZ = 'Asia/Kolkata';

const escape = (value) => String(value ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const shorten = (value, max) => (String(value).length > max ? `${String(value).slice(0, max - 1)}…` : String(value));
const LABEL = { blog_article: '📝 Blog', ig_caption: '📸 Caption', reel_idea: '🎬 Reel', newsletter: '💌 Newsletter', short_post: '💬 Short post' };
const when = (stamp) => DateTime.fromISO(stamp).setZone(TZ).toFormat(S.IS_DEMO ? 'HH:mm' : 'ccc d LLL, HH:mm');

const lines = rows.map((row, index) =>
  `${index + 1}. ${LABEL[row.asset_type] || row.asset_type}: ${escape(shorten(row.title, 55))} · score ${row.seo_score} · ${when(row.scheduled_for)}`);

const failed = results.filter((result) => !result.ai_ok);
const fallbacks = results.filter((result) => result.ai_provider === 'groq');
const withIssues = rows.filter((row) => row.issues).length;
const factIssues = rows.filter((row) => row.issues.includes('FACT:')).length;

const header = [
  `🪔 <b>Content ready for approval: ${rows.length} items</b>`,
  `<i>${escape(B.campaign_name)} · ${rows[0].batch_id}${S.IS_DEMO ? ` · DEMO MODE (1 day = ${S.DEMO_MINUTES_PER_DAY} min)` : ''}</i>`,
  '',
];
const footer = [''];
if (withIssues) footer.push(`⚠️ ${withIssues} item(s) have notes in the <b>issues</b> column${factIssues ? ` (${factIssues} with FACT problems, check these first)` : ''}.`);
if (fallbacks.length) footer.push(`🔁 Groq fallback used for: ${fallbacks.map((result) => escape(result.label)).join(', ')}.`);
if (failed.length) footer.push(`❌ Not generated: ${failed.map((result) => escape(result.label)).join(', ')}. Run Lane 1 again later.`);
footer.push('Approve in the CONTENT tab: set <b>status</b> to <code>approved</code>, <code>rejected</code> or <code>needs_changes</code>.');
if (S.SHEET_URL && !String(S.SHEET_URL).includes('__KAYA_SHEET_ID__')) footer.push(`<a href="${escape(S.SHEET_URL)}">Open the sheet</a>`);

// Telegram allows 4,096 characters: keep whole lines only (never cut through an HTML tag).
const budget = 3900 - header.join('\n').length - footer.join('\n').length;
const list = [];
let used = 0;
for (const line of lines) {
  if (used + line.length + 1 > budget) {
    list.push(`…and ${lines.length - list.length} more in the sheet`);
    break;
  }
  list.push(line);
  used += line.length + 1;
}

const text = [...header, ...list, ...footer].join('\n');
return [{ json: { chat_id: String(S.TELEGRAM_OWNER_CHAT_ID), text, item_count: rows.length } }];

// Write what happened to EVENTS_LOG (SPEC section 5.6), so Lane 8 can report on it:
// one row per content item, one per AI job (+ fallback / failure rows), the approval request
// and a run summary.
const S = $('Lane 1 · Settings to object').first().json;
const rows = $('Lane 1 · Schedule & assign IDs').all().map((item) => item.json);
const results = $('Lane 1 · Loop over asset jobs').all(0).map((item) => item.json);
const telegram = $input.first().json;
const TZ = 'Asia/Kolkata';
const LANE = 1;

const now = $now.setZone(TZ);
const stamp = now.toFormat("yyyy-MM-dd'T'HH:mm:ssZZ");
const usedIds = new Set();
function eventId() {
  let id;
  do {
    id = `EV-${now.toFormat('yyyyMMddHHmmssSSS')}-${Math.random().toString(36).slice(2, 6).toUpperCase().padEnd(4, '0')}`;
  } while (usedIds.has(id));
  usedIds.add(id);
  return id;
}
function event(fields) {
  return {
    event_id: eventId(),
    ts: stamp,
    lane: LANE,
    event_type: fields.event_type,
    entity_type: fields.entity_type,
    entity_id: fields.entity_id || '',
    status_from: fields.status_from || '',
    status_to: fields.status_to || '',
    channel: fields.channel || '',
    detail: String(fields.detail || '').slice(0, 200),
    meta_json: JSON.stringify(fields.meta || {}),
    execution_id: String($execution.id),
    demo_mode: S.IS_DEMO ? 'TRUE' : 'FALSE',
  };
}

const batchId = rows[0].batch_id;
const events = [];

for (const row of rows) {
  events.push(event({
    event_type: 'content_generated', entity_type: 'content', entity_id: row.content_id,
    status_to: 'pending_approval', channel: 'sheet',
    detail: `${row.asset_type}: ${row.title}`,
    meta: { batch_id: batchId, asset_type: row.asset_type, seo_score: row.seo_score, issue_count: row.issues ? row.issues.split(' | ').length : 0, ai_provider: row.ai_provider, scheduled_for: row.scheduled_for },
  }));
}

for (const result of results) {
  const meta = { batch_id: batchId, job_type: result.job_type, provider: result.ai_provider, model: result.ai_model, ok: result.ai_ok, duration_ms: result.duration_ms };
  events.push(event({
    event_type: 'ai_call', entity_type: 'ai', entity_id: result.request_id, channel: 'ai',
    detail: `${result.label}: ${result.ai_ok ? 'ok' : 'failed'} via ${result.ai_provider}`, meta,
  }));
  if (result.ai_provider === 'groq') {
    events.push(event({
      event_type: 'ai_fallback', entity_type: 'ai', entity_id: result.request_id, channel: 'ai',
      detail: `Gemini failed, used Groq: ${result.fallback_reason}`, meta: { ...meta, reason: result.fallback_reason },
    }));
  }
  if (!result.ai_ok) {
    events.push(event({
      event_type: 'ai_failed', entity_type: 'ai', entity_id: result.request_id, channel: 'ai',
      detail: result.ai_error, meta: { ...meta, error: result.ai_error },
    }));
  }
}

const telegramOk = !telegram.error && (telegram.ok === true || !!telegram.result || !!telegram.message_id);
events.push(event({
  event_type: 'approval_requested', entity_type: 'batch', entity_id: batchId, channel: 'telegram_owner',
  detail: telegramOk ? `Asked the owner to approve ${rows.length} items` : `Telegram message failed: ${telegram.error?.message || 'unknown error'}`,
  meta: { items: rows.length, telegram_ok: telegramOk },
}));

const startedAt = DateTime.fromFormat(batchId.slice(2), 'yyyyMMdd-HHmmss', { zone: TZ }); // batch id = run start
events.push(event({
  event_type: 'lane_run', entity_type: 'system', entity_id: batchId, channel: 'sheet',
  detail: `Lane 1 created ${rows.length} items, ${results.filter((result) => !result.ai_ok).length} AI job(s) failed`,
  meta: {
    items_created: rows.length,
    ai_jobs: results.length,
    ai_failed: results.filter((result) => !result.ai_ok).length,
    ai_fallbacks: results.filter((result) => result.ai_provider === 'groq').length,
    duration_seconds: Math.round(now.diff(startedAt, 'seconds').seconds),
  },
}));

return events.map((json) => ({ json }));
